#include <algorithm>
#include <string>
#include <iostream>
using namespace std;

char x[256];
typedef long long ll;

int n;
ll hasha[1000001], hashb[1000001], powers[1000001];
string a, b;

void pre()
{
    x['E'] = 'W';
    x['W'] = 'E';
    x['N'] = 'S';
    x['S'] = 'N';

    powers[0] = 1;
    powers[1] = 10;
    for (int i = 2; i <= 1000000; i++)
        powers[i] = 10 * powers[i - 1];
}

void calc()
{
    for (int i = 1; i <= n; i++)
        hasha[i] = 10 * hasha[i - 1] + a[i - 1];

    for (int i = 1; i <= n; i++)
        hashb[i] = hashb[i - 1] + powers[i - 1] * b[b.length() - i];
}

void invertDirections(string& s)
{
    for (size_t i = 0; i < s.length(); i++)
        s[i] = x[static_cast<unsigned char>(s[i])];
}

int main()
{
    cin >> n;
    pre();
    cin >> a >> b;

    invertDirections(a);
    calc();

    int flag = 1;
    for (int i = 1; i <= n; i++)
    {
        if (hasha[i] == hashb[i])
        {
            if (a.substr(0, i) == b.substr(n - 1 - i, i))
                flag = 0;
        }
    }

    cout << (flag ? "YES" : "NO");
    return 0;
}

